<div class="page-title clearfix"><h1>Email Marketing</h1><div class="title-button-group"><a href="<?php echo site_url('email_marketing/dashboard'); ?>" class="btn btn-default">Dashboard</a> <a href="<?php echo site_url('email_marketing/contacts'); ?>" class="btn btn-default">Contacts</a> <a href="<?php echo site_url('email_marketing/create'); ?>" class="btn btn-primary">Create Campaign</a> <a href="<?php echo site_url('email_marketing/templates'); ?>" class="btn btn-default">Templates</a> <a href="<?php echo site_url('email_marketing/reports'); ?>" class="btn btn-default">Reports</a> <a href="<?php echo site_url('email_marketing/automation'); ?>" class="btn btn-default">Automation</a> <a href="<?php echo site_url('email_marketing/settings'); ?>" class="btn btn-default">Settings</a></div></div>
<div class="alert alert-info">Only contacts with Marketing Consent = Opted In are eligible. Suppressed and Do Not Contact records are always excluded.</div>
<div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Campaign</th><th>Subject</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($campaigns as $c): ?><tr><td><?php echo esc($c->name); ?></td><td><?php echo esc($c->subject); ?></td><td><span class="badge bg-secondary"><?php echo esc($c->status); ?></span></td><td><?php echo esc($c->created_at); ?></td><td><a href="<?php echo site_url('email_marketing/edit/'.$c->id); ?>">Edit</a> | <a href="<?php echo site_url('email_marketing/logs/'.$c->id); ?>">Delivery log</a> <form method="post" action="<?php echo site_url('email_marketing/queue/'.$c->id); ?>" style="display:inline" onsubmit="return confirm('Queue eligible recipients for this campaign? Test mode will restrict delivery to the Test recipient.');"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><button class="btn btn-link p0">Queue campaign</button></form> <form method="post" action="<?php echo site_url('email_marketing/send_test/'.$c->id); ?>" style="display:inline" onsubmit="return confirm('Queue exactly one test email?');"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><button class="btn btn-link p0">Queue test</button></form> <form method="post" action="<?php echo site_url('email_marketing/delete/'.$c->id); ?>" style="display:inline" onsubmit="return confirm('Delete this campaign and its delivery log? This cannot be undone.');"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><button class="btn btn-link p0 text-danger">Delete</button></form></td></tr><?php endforeach; if(!$campaigns): ?><tr><td colspan="5">No campaigns.</td></tr><?php endif; ?></tbody></table></div></div>
